// Computer-assisted proof of a quadratic, generically unfolding homoclinic tangency
// for the Poincare map of the Rossler system
//     x' = -(y+z),  y' = x + a y,  z' = b + z (x - c),   a = b = 0.2,
// on the section {x = 0, x' > 0}, as c varies in a small interval J.
// [near57 variant 'tangency_57_n6': generated by make_variant.py from tangency_cap.cpp;
//  only numerical parameters differ (tangency near c = 5.7, n = 6, N = K2 + n = 15).]
//
// Uses CAPD::DynSys (interval arithmetic, C^2-Lohner integrator, rigorous Poincare maps).
// All quantities printed as intervals are rigorous enclosures. Every "CHECK" must print true.

#include <iostream>
#include <iomanip>
#include <cmath>
#include <vector>
#include <string>
#include "capd/capdlib.h"

using namespace capd;
using namespace std;
typedef interval I;

// ------------------------------------------------------------------------------------
// Dynamical system: 4D extended field (c is a state variable with c' = 0).
// ------------------------------------------------------------------------------------
static IMap*               VF;
static IC2OdeSolver*       SOLVER;
static ICoordinateSection* SECTION;
static IC2PoincareMap*     PM;

static bool ALLOK = true;
static void CHECK(const string& name, bool ok) {
  cout << "CHECK  " << left << setw(62) << name << " : " << (ok ? "true" : "FALSE") << endl;
  ALLOK = ALLOK && ok;
}

static double mag(const I& x) { return std::max(fabs(x.leftBound()), fabs(x.rightBound())); }
static I sym(double r) { return I(-r, r); }
static I symI(const I& x) { double m = mag(x); return I(-m, m); }
static I sqrI(const I& x) { return sqr(x); }   // proper interval square (>= 0)

// Exact enclosure of a decimal literal "[-]ddd.ddd" (no exponent, at most 15 significant digits):
// numerator and 10^k are exact doubles, and the interval division is outward rounded.
static I dec(const string& s) {
  bool neg = (s[0] == '-');
  string t = (s[0] == '-' || s[0] == '+') ? s.substr(1) : s;
  size_t p = t.find('.');
  string digits = (p == string::npos) ? t : t.substr(0, p) + t.substr(p + 1);
  int k = (p == string::npos) ? 0 : (int)(t.size() - p - 1);
  long long num = stoll(digits);
  if (num > (1LL << 53) || k > 22) throw runtime_error("dec: literal too long: " + s);
  double ten = 1.; for (int i = 0; i < k; i++) ten *= 10.;   // exact for k <= 22
  I r = I((double)num) / I(ten);
  return neg ? -r : r;
}

static IMatrix inv2(const IMatrix& M) {
  I det = M[0][0] * M[1][1] - M[0][1] * M[1][0];
  if (det.contains(0.)) throw runtime_error("inv2: singular interval matrix");
  IMatrix R(2, 2);
  R[0][0] =  M[1][1] / det;  R[0][1] = -M[0][1] / det;
  R[1][0] = -M[1][0] / det;  R[1][1] =  M[0][0] / det;
  return R;
}
static IMatrix Id2() { IMatrix R(2, 2); R[0][0] = 1.; R[1][1] = 1.; return R; }

// Jet of P^n (w.r.t. initial (y,z) and c) enclosed over a C^2 set
struct Jet {
  IVector v;       // value (y,z)
  IMatrix D;       // d(y,z)/d(y0,z0)
  IVector Dc;      // d(y,z)/dc
  I H[2][2][2];    // TRUE second derivatives d^2 (y,z)_i / d(y0,z0)_a d(y0,z0)_b
  Jet() : v(2), D(2, 2), Dc(2) {}
};

static Jet jetFromSet(C2Rect2Set& s, int n) {
  IMatrix dF(4, 4); IHessian Hf(4, 4); I T;
  IVector P = (*PM)(s, dF, Hf, T, n);
  IMatrix DP(4, 4); IHessian D2P(4, 4);
  PM->computeDP(P, dF, Hf, DP, D2P, T);
  Jet j;
  for (int i = 0; i < 2; i++) {
    j.v[i]  = P[i + 1];
    j.Dc[i] = DP[i + 1][3];
    for (int k = 0; k < 2; k++) j.D[i][k] = DP[i + 1][k + 1];
    // CAPD returns Taylor coefficients: diagonal entries are (1/2) d^2/dx^2
    for (int a = 0; a < 2; a++)
      for (int b = 0; b < 2; b++)
        j.H[i][a][b] = (a == b ? I(2.) : I(1.)) * D2P(i + 1, a + 1, b + 1);
  }
  return j;
}

static Jet jetBox(const IVector& yz, const I& c, int n) {
  IVector u(4); u[0] = 0.; u[1] = yz[0]; u[2] = yz[1]; u[3] = c;
  C2Rect2Set s(u);
  return jetFromSet(s, n);
}

// Affine initial set  X0(s,v,c) = (0, pc + s*eu + v*es, c),
//   pc = phat + dphat*(c-cmid) + Rp,   s in sv, v in vv, c in cmid + dc
static Jet jetCurve(const IVector& phat, const IVector& dphat, const IVector& Rp,
                    const IMatrix& E, double s0, const I& ds, const I& vv,
                    double cmid, const I& dc, int n) {
  IVector x(4);
  x[0] = 0.;
  x[1] = phat[0] + I(s0) * E[0][0];
  x[2] = phat[1] + I(s0) * E[1][0];
  x[3] = cmid;
  IMatrix C(4, 4);
  C[0][0] = 1.;
  C[1][1] = E[0][0]; C[2][1] = E[1][0];
  C[1][2] = E[0][1]; C[2][2] = E[1][1];
  C[1][3] = dphat[0]; C[2][3] = dphat[1]; C[3][3] = 1.;
  IVector r0(4); r0[0] = 0.; r0[1] = ds; r0[2] = vv; r0[3] = dc;
  IVector r(4);  r[0] = 0.;  r[1] = Rp[0]; r[2] = Rp[1]; r[3] = 0.;
  // use an exactly representable centre; rounding errors of x go into the box part r
  IVector xc = midVector(x);
  r += (x - xc);
  C2Rect2Set s(xc, C, r0, r);
  return jetFromSet(s, n);
}

// Local map f_c(u,v) = E^{-1}(P_c(p_c + E(u,v)) - p_c): derivative enclosures
struct Local {
  I a[2][2];      // Df
  I h[2][2][2];   // D^2 f (true second derivatives)
  I fc[2];        // d f / dc  (with p_c moving)
};
static Local localDerivs(const Jet& j, const IMatrix& E, const IMatrix& Ei, const IVector& dp) {
  Local L;
  IMatrix A = Ei * j.D * E;
  for (int i = 0; i < 2; i++) for (int k = 0; k < 2; k++) L.a[i][k] = A[i][k];
  for (int i = 0; i < 2; i++)
    for (int p = 0; p < 2; p++)
      for (int q = 0; q < 2; q++) {
        I s = 0.;
        for (int m = 0; m < 2; m++) {
          I t = 0.;
          for (int a = 0; a < 2; a++)
            for (int b = 0; b < 2; b++) t += j.H[m][a][b] * E[a][p] * E[b][q];
          s += Ei[i][m] * t;
        }
        L.h[i][p][q] = s;
      }
  IVector fcv = Ei * (j.Dc + (j.D - Id2()) * dp);
  L.fc[0] = fcv[0]; L.fc[1] = fcv[1];
  return L;
}

// ------------------------------------------------------------------------------------
int main(int argc, char* argv[]) {
  cout.precision(17);
  cout << boolalpha;
  try {
    // ---------------- parameters of the proof ----------------
    const double cshift = (argc > 3) ? atof(argv[3]) : 0.0;   // for negative tests only
    const double cmid  = 5.6994199824407454 + cshift;   // numerical tangency parameter
    const double epsc  = (argc > 1) ? atof(argv[1]) : 1e-8;   // J = cmid + [-epsc, epsc]
    const int    K2    = 9;                    // iterates from W^u_loc to the fold
    const int    N     = K2 + 6;                // iterates from W^u_loc to the tip near p
    const double smid  = 5.9787937263417563e-04;      // numerical critical parameter on W^u_loc
    const double Delta = (argc > 2) ? atof(argv[2]) : 1e-9;   // S = smid + [-Delta, Delta]
    const double delta_u = 7e-4;                // W^u_loc domain |u| <= delta_u
    const double rs = 1e-6, ru = 1e-6;          // W^s_loc box |u|<=ru, |v|<=rs

    I a = I(2) / I(10), b = I(2) / I(10);
    VF = new IMap("par:a,b;var:x,y,z,c;fun:-(y+z),x+a*y,b+z*(x-c),0;");
    VF->setParameter("a", a);
    VF->setParameter("b", b);
    SOLVER  = new IC2OdeSolver(*VF, 20);
    SECTION = new ICoordinateSection(4, 0);
    PM      = new IC2PoincareMap(*SOLVER, *SECTION, poincare::MinusPlus);

    // J is the exact interval between the two doubles cL < cR (no rounding issue)
    const double cL = cmid - epsc, cR = cmid + epsc;
    const I J  = I(cL, cR);
    const I dcJ = J - I(cmid);           // contains c - cmid for every c in J
    cout << "a = b = 0.2,  J = " << J << ",  N = " << N << ",  S = " << smid << " +- " << Delta << endl;

    // ---------------- approximate data (non-rigorous inputs) ----------------
    IVector qt(2); qt[0] = -8.3802521043854075 + (-1.1890042497036399) * cshift; qt[1] = 0.029592632330554456 + (-0.0044342237160744672) * cshift;
    IMatrix E(2, 2);
    E[0][0] = -0.99999989715156368;  E[0][1] = -0.63327279952325022;
    E[1][0] = -0.00045353815949183155;  E[1][1] = -0.77392865393651467;
    IMatrix Ei = inv2(E);   // rigorous enclosure of E^{-1}
    IVector eu(2), es(2); eu[0] = E[0][0]; eu[1] = E[1][0]; es[0] = E[0][1]; es[1] = E[1][1];

    // ======================= 1. fixed point p_c (Krawczyk) =======================
    // approximate dp/dc (non-rigorous input, only used to centre the Krawczyk boxes)
    const double dpy = -1.1890042497036399, dpz = -0.0044342237160744672;
    IVector QKraw(2);   // the Krawczyk box used for c in J (uniqueness domain)
    auto krawczyk = [&](const I& cc, double ry, double rz, IVector& Kout, IVector* Qout = nullptr) -> bool {
      double c0 = cc.mid().leftBound();
      IVector q0(2); q0[0] = qt[0].leftBound() + dpy * (c0 - cmid); q0[1] = qt[1].leftBound() + dpz * (c0 - cmid);
      IVector Q(2); Q[0] = q0[0] + sym(ry); Q[1] = q0[1] + sym(rz);
      Jet j0 = jetBox(q0, cc, 1);
      Jet jQ = jetBox(Q, cc, 1);
      IMatrix DF = jQ.D - Id2();
      // approximate inverse (any matrix works for Krawczyk)
      double m00 = DF[0][0].mid().leftBound(), m01 = DF[0][1].mid().leftBound();
      double m10 = DF[1][0].mid().leftBound(), m11 = DF[1][1].mid().leftBound();
      double det = m00 * m11 - m01 * m10;
      IMatrix Cm(2, 2); Cm[0][0] = m11 / det; Cm[0][1] = -m01 / det; Cm[1][0] = -m10 / det; Cm[1][1] = m00 / det;
      IVector K = q0 - Cm * (j0.v - q0) + (Id2() - Cm * DF) * (Q - q0);
      Kout = K;
      if (Qout) *Qout = Q;
      return subsetInterior(K, Q);
    };
    IVector KJ(2), KL(2), KR(2), KM(2);
    CHECK("Krawczyk: unique fixed point p_c of P_c in Q, all c in J", krawczyk(J, 3e-8, 1e-9, KJ, &QKraw));
    CHECK("Krawczyk: fixed point at c = cL", krawczyk(I(cL), 1e-11, 1e-11, KL));
    CHECK("Krawczyk: fixed point at c = cR", krawczyk(I(cR), 1e-11, 1e-11, KR));
    CHECK("Krawczyk: fixed point at c = cmid", krawczyk(I(cmid), 1e-11, 1e-11, KM));
    CHECK("cL, cmid, cR lie in J", J.contains(cL) && J.contains(cR) && J.contains(cmid));
    CHECK("fixed points at cL, cmid, cR lie in the J-branch box", subset(KL, KJ) && subset(KR, KJ) && subset(KM, KJ));
    cout << "p_c (c in J)  in " << KJ << endl;
    cout << "p_cmid        in " << KM << endl;

    Jet jK = jetBox(KJ, J, 1);
    IVector dp = -(inv2(jK.D - Id2()) * jK.Dc);       // dp/dc enclosure over J
    cout << "dp/dc         in " << dp << endl;

    // ======================= 2. saddle and dissipativity =======================
    IMatrix A0 = Ei * jK.D * E;
    I tr = A0[0][0] + A0[1][1];
    I dt = A0[0][0] * A0[1][1] - A0[0][1] * A0[1][0];
    cout << "Df(p) in local coords = " << A0 << endl;
    cout << "trace = " << tr << "   det = " << dt << endl;
    I chi1 = 1. - tr + dt, chim1 = 1. + tr + dt;
    CHECK("saddle: chi(1) > 0 and chi(-1) < 0 (one eigenvalue < -1, one in (-1,1))",
          chi1 > 0. && chim1 < 0.);
    CHECK("dissipative saddle: |det DP(p_c)| < 1", mag(dt) < 1.);

    // ---- the statement of the theorem as printed in the paper (decimal boxes and bounds) ----
    // (skipped in the negative tests, where J is shifted)
    const char* THM = "statement";
    const char* QK_dec[4] = {"-8.3802521343", "-8.3802520744", "0.029592631331", "0.029592633330"};  // Q_K: uniqueness box
    const char* Q_dec[4]  = {"-8.380252117", "-8.380252092", "0.0295926320", "0.0295926327"};  // Q: location box
    const char* LAMU_dec[2] = {"-2.4040", "-2.4037"};   // claimed range of lambda_u
    const char* DET_dec   = "0.00000002";                 // claimed bound |lambda_u lambda_s| < DET
    const char* DIST_dec  = "0.00000004";                 // claimed bound |q_* - p| < DIST
    if (cshift == 0.0) {
      IVector QKout(2), Qin(2);   // outer hull of Q_K, inner box of Q
      QKout[0] = I(dec(QK_dec[0]).leftBound(), dec(QK_dec[1]).rightBound());
      QKout[1] = I(dec(QK_dec[2]).leftBound(), dec(QK_dec[3]).rightBound());
      Qin[0] = I(dec(Q_dec[0]).rightBound(), dec(Q_dec[1]).leftBound());
      Qin[1] = I(dec(Q_dec[2]).rightBound(), dec(Q_dec[3]).leftBound());
      CHECK(string(THM) + ": box Q_K lies in the Krawczyk box (uniqueness)", subset(QKout, QKraw));
      CHECK(string(THM) + ": K_J lies in the box Q (location of p_c)", subset(KJ, Qin));
      // |lambda_s| = |det|/|lambda_u| <= |det|/(mig tr - 1), and lambda_u = tr - lambda_s
      I mtr = (tr < 0.) ? -tr : tr;
      I sb = I(mag(dt)) / (I(mtr.leftBound()) - 1.);
      I lam = tr + sym(sb.rightBound());
      cout << "lambda_u in " << lam << endl;
      CHECK(string(THM) + ": lambda_u in the stated range", tr < 0. &&
            lam.leftBound() >= dec(LAMU_dec[0]).rightBound() && lam.rightBound() <= dec(LAMU_dec[1]).leftBound());
      CHECK(string(THM) + ": |lambda_u lambda_s| = |det| < stated bound", mag(dt) < dec(DET_dec).leftBound());
    }

    // ======================= 3. local unstable manifold (C^2 graph transform) =======================
    // W^u_loc = graph v = w_c(u), |u| <= delta_u, with |w|<=rho, |w'|<=Lu, |w''|<=Ku, |dw/dc|<=Mu
    double rho = 1e-5;  // a priori v-range of the box, verified below
    IVector Bu(2);
    {
      IVector loc(2); loc[0] = sym(delta_u); loc[1] = sym(rho);
      Bu = KJ + E * loc;
    }
    Jet jU = jetBox(Bu, J, 1);
    Local LU = localDerivs(jU, E, Ei, dp);
    cout << "W^u box: Df = [[" << LU.a[0][0] << ", " << LU.a[0][1] << "], [" << LU.a[1][0] << ", " << LU.a[1][1] << "]]" << endl;

    double Lu = 0, Ku = 0, Mu = 0;
    auto wuMaps = [&](double L, double K, double M, I& wp, I& wpp, I& wc, I& m, I& theta) {
      I wq = sym(L), wqq = sym(K), wcc = sym(M);
      I phi1 = LU.a[0][0] + LU.a[0][1] * wq;
      I psi1 = LU.a[1][0] + LU.a[1][1] * wq;
      I phi2 = LU.h[0][0][0] + 2. * LU.h[0][0][1] * wq + LU.h[0][1][1] * sqrI(wq) + LU.a[0][1] * wqq;
      I psi2 = LU.h[1][0][0] + 2. * LU.h[1][0][1] * wq + LU.h[1][1][1] * sqrI(wq) + LU.a[1][1] * wqq;
      wp  = psi1 / phi1;
      wpp = (psi2 * phi1 - psi1 * phi2) / (phi1 * phi1 * phi1);
      wc  = LU.fc[1] + LU.a[1][1] * wcc - wp * (LU.fc[0] + LU.a[0][1] * wcc);
      m   = I(std::min(fabs(phi1.leftBound()), fabs(phi1.rightBound())));
      if (phi1.contains(0.)) m = 0.;
      I mA = I(std::min(fabs(LU.a[0][0].leftBound()), fabs(LU.a[0][0].rightBound())));
      I kden = 1. - I(mag(LU.a[0][1])) * L / mA;
      if (!(kden > 0.)) throw runtime_error("W^u: kappa denominator not positive");
      I kappa = (I(mag(LU.a[0][1])) / mA) / kden;
      theta = I(mag(LU.a[1][0])) * kappa + I(mag(LU.a[1][1])) * (L * kappa + 1.);
    };
    for (int it = 0; it < 30; it++) {   // find consistent bounds (heuristic), verified afterwards
      I wp, wpp, wc, m, th; wuMaps(Lu, Ku, Mu, wp, wpp, wc, m, th);
      Lu = 1.05 * mag(wp) + 1e-14; Ku = 1.05 * mag(wpp) + 1e-14; Mu = 1.05 * mag(wc) + 1e-14;
    }
    {
      I wp, wpp, wc, m, th; wuMaps(Lu, Ku, Mu, wp, wpp, wc, m, th);
      cout << "W^u bounds: Lu = " << Lu << "  Ku = " << Ku << "  Mu = " << Mu << endl;
      CHECK("W^u: 0 not in [a11] (so mig[a11] = min of endpoint moduli)", !LU.a[0][0].contains(0.));
      CHECK("W^u: expansion along graph  min|phi'| > 1", m > 1.);
      CHECK("W^u: graph transform keeps |w'| <= Lu", subset(wp, sym(Lu)));
      CHECK("W^u: graph transform keeps |w''| <= Ku", subset(wpp, sym(Ku)));
      CHECK("W^u: graph transform keeps |dw/dc| <= Mu", subset(wc, sym(Mu)));
      I psiBound = I(mag(LU.a[1][0])) * delta_u + I(mag(LU.a[1][1])) * rho;
      CHECK("W^u: graph stays in box  |psi| <= rho", psiBound < rho);
      CHECK("W^u: |w| <= Lu*delta_u <= rho", I(Lu) * delta_u < rho);
      CHECK("W^u: graph transform is a C^0 contraction (theta < 1)", th < 1.);
      cout << "     contraction theta = " << th << endl;
    }

    // ======================= 4. local stable manifold (C^2 graph transform) =======================
    // W^s_loc = graph u = sigma_c(v), |v| <= rs, |sigma'|<=Ls, |sigma''|<=Ks, |dsigma/dc|<=Ms
    IVector Bs(2);
    {
      IVector loc(2); loc[0] = sym(ru); loc[1] = sym(rs);
      Bs = KJ + E * loc;
    }
    Jet jS = jetBox(Bs, J, 1);
    Local LS = localDerivs(jS, E, Ei, dp);
    cout << "W^s box: Df = [[" << LS.a[0][0] << ", " << LS.a[0][1] << "], [" << LS.a[1][0] << ", " << LS.a[1][1] << "]]" << endl;
    double Ls = 0, Ks = 0, Ms = 0;
    auto wsMaps = [&](double L, double K, double M, I& sp, I& spp, I& sc, I& den) {
      I sq = sym(L), sqq = sym(K), scc = sym(M);
      den = LS.a[0][0] - sq * LS.a[1][0];
      sp  = (sq * LS.a[1][1] - LS.a[0][1]) / den;
      I spb = sym(mag(sp));
      I F2p = LS.a[1][0] * spb + LS.a[1][1];
      I Q1 = LS.h[0][0][0] * sqrI(spb) + 2. * LS.h[0][0][1] * spb + LS.h[0][1][1];
      I Q2 = LS.h[1][0][0] * sqrI(spb) + 2. * LS.h[1][0][1] * spb + LS.h[1][1][1];
      spp = (sqq * sqrI(F2p) + sq * Q2 - Q1) / den;
      sc  = (sq * LS.fc[1] + scc - LS.fc[0]) / den;
    };
    for (int it = 0; it < 60; it++) {
      I sp, spp, sc, den; wsMaps(Ls, Ks, Ms, sp, spp, sc, den);
      Ls = 1.05 * mag(sp) + 1e-14; Ks = 1.05 * mag(spp) + 1e-14; Ms = 1.05 * mag(sc) + 1e-14;
    }
    {
      I sp, spp, sc, den; wsMaps(Ls, Ks, Ms, sp, spp, sc, den);
      cout << "W^s bounds: Ls = " << Ls << "  Ks = " << Ks << "  Ms = " << Ms << endl;
      CHECK("W^s: graph transform keeps |sigma'| <= Ls", subset(sp, sym(Ls)));
      CHECK("W^s: graph transform keeps |sigma''| <= Ks", subset(spp, sym(Ks)));
      CHECK("W^s: graph transform keeps |dsigma/dc| <= Ms", subset(sc, sym(Ms)));
      I mden = I(std::min(fabs(den.leftBound()), fabs(den.rightBound())));
      CHECK("W^s: 0 not in [a11] (so mig[a11] = min of endpoint moduli)", !LS.a[0][0].contains(0.));
      CHECK("W^s: C^0 contraction  1/min|a11 - sigma' a21| < 1", !den.contains(0.) && mden > 1.);
      I f2range = I(mag(LS.a[1][0])) * ru + I(mag(LS.a[1][1])) * rs;
      CHECK("W^s: v-image stays in [-rs,rs]", f2range < rs);
      I mA = I(std::min(fabs(LS.a[0][0].leftBound()), fabs(LS.a[0][0].rightBound())));
      I hden = mA - I(Ls) * mag(LS.a[1][0]);
      CHECK("W^s: |h'| lower bound mA - Ls|a21| > 0", hden > 0.);
      I hroot = (I(mag(LS.a[0][1])) + I(Ls) * mag(LS.a[1][1])) * rs / hden;
      CHECK("W^s: preimage root stays in [-ru,ru]", hroot < ru);
      CHECK("W^s: restricted map on graph contracts", I(mag(LS.a[1][0])) * Ls + mag(LS.a[1][1]) < 1.);
    }

    // ======================= 5. the tangency =======================
    IVector phat(2), dphat(2);
    phat[0] = KM[0].mid().leftBound(); phat[1] = KM[1].mid().leftBound();
    dphat[0] = dp[0].mid().leftBound(); dphat[1] = dp[1].mid().leftBound();
    // p_c - phat - dphat (c - cmid)  in  (KM - phat) + (dp - dphat)(J - cmid)
    IVector RpJ = (KM - phat) + (dp - dphat) * dcJ;

    // slope of W^u_loc at the fixed point: w_c'(0) = t, (1,t) unstable eigenvector of Df_c(0,0):
    //   t = a21 / (a11 + a12 t - a22),  |t| <= Lu
    auto slope0 = [&](const IMatrix& A) {
      I t = A[1][0] / (A[0][0] + A[0][1] * sym(Lu) - A[1][1]);
      if (!subset(t, sym(Lu))) throw runtime_error("slope0: inconsistent");
      return mag(t);
    };
    double t0J = slope0(A0);
    double t0L = slope0(Ei * jetBox(KL, I(cL), 1).D * E);
    double t0R = slope0(Ei * jetBox(KR, I(cR), 1).D * E);
    cout << "|w'(0)| <= " << t0J << " (J),  " << t0L << " (cL),  " << t0R << " (cR)" << endl;
    // |w(s)| <= |w'(0)||s| + Ku s^2/2 ,  |w'(s)| <= |w'(0)| + Ku |s|
    auto wRange  = [&](const I& s, double t0) { double m = mag(s); return sym((I(t0) * m + I(Ku) * m * m / 2.).rightBound()); };
    auto wpRange = [&](const I& s, double t0) { double m = mag(s); return sym((I(t0) + I(Ku) * m).rightBound()); };

    struct G { I g, gs, gss, gc, U, V; };
    // local tip quantities from a jet
    auto Hb = [&](const Jet& jt, const IVector& x, const IVector& y) {
      IVector r(2);
      for (int i = 0; i < 2; i++) {
        r[i] = 0.;
        for (int a2 = 0; a2 < 2; a2++)
          for (int b2 = 0; b2 < 2; b2++) r[i] += jt.H[i][a2][b2] * x[a2] * y[b2];
      }
      return r;
    };
    auto tipQuantities = [&](const Jet& jt, const IVector& pc, const I& wp, const I& wpp, bool withC) {
      G r;
      IVector Deu = jt.D * eu, Des = jt.D * es;
      IVector Gs  = Deu + Des * wp;
      IVector Gss = Hb(jt, eu, eu) + Hb(jt, eu, es) * (2. * wp) + Hb(jt, es, es) * sqrI(wp) + Des * wpp;
      IVector UV = Ei * (jt.v - pc), UVs = Ei * Gs, UVss = Ei * Gss;
      r.U = UV[0]; r.V = UV[1];
      I sp = sym(Ls), spp = sym(Ks), sc = sym(Ms);
      r.g   = UV[0] - I(Ls) * symI(UV[1]);
      r.gs  = UVs[0] - sp * UVs[1];
      r.gss = UVss[0] - spp * sqrI(UVs[1]) - sp * UVss[1];
      if (withC) {
        IVector Gc = (jt.D - Id2()) * dp + Des * sym(Mu) + jt.Dc;   // = d/dc Gamma - dp/dc
        IVector UVc = Ei * Gc;
        r.gc = UVc[0] - sc - sp * UVc[1];
        cout << "           D e_u in " << Deu << "\n           D e_s in " << Des << endl;
        cout << "           (U_c,V_c) in " << UVc << endl;
      } else r.gc = 0.;
      return r;
    };

    // (C) sign change of max_s g(s,c) between cL and cR
    {
      IVector phL(2); phL[0] = KL[0].mid().leftBound(); phL[1] = KL[1].mid().leftBound();
      IVector zero(2); zero[0] = 0.; zero[1] = 0.;
      IVector RpL = KL - phL;
      Jet jm = jetCurve(phL, zero, RpL, E, smid, I(0.), wRange(I(smid), t0L), cL, I(0.), N);
      G gm = tipQuantities(jm, KL, wpRange(I(smid), t0L), sym(Ku), false);
      Jet jSS = jetCurve(phL, zero, RpL, E, smid, sym(Delta), wRange(I(smid) + sym(Delta), t0L), cL, I(0.), N);
      G gS = tipQuantities(jSS, KL, wpRange(I(smid) + sym(Delta), t0L), sym(Ku), false);
      cout << "c = cL:  g(smid) in " << gm.g << "   g_s(smid) in " << gm.gs << endl;
      cout << "         g_ss on S in " << gS.gss << "   V on S in " << gS.V << endl;
      bool neg = gS.gss < 0.;
      I gssMax = I(-std::min(fabs(gS.gss.leftBound()), fabs(gS.gss.rightBound())));
      // sup_{|h|<=Delta} g(smid) + g_s h + (1/2) gssMax h^2  <=  g + gs^2 / (2 |gssMax|)
      I supBound = gm.g + sqrI(I(mag(gm.gs))) / (2. * (-gssMax));
      cout << "         sup_S g(.,cL) <= " << supBound.rightBound() << endl;
      CHECK("(C) g(s,cL) < 0 for all s in S", neg && supBound < 0.);
      CHECK("(C) |V| <= rs at c = cL (tip inside W^s_loc chart)", subset(gS.V, sym(rs)));

      IVector phR(2); phR[0] = KR[0].mid().leftBound(); phR[1] = KR[1].mid().leftBound();
      IVector RpR = KR - phR;
      Jet jr = jetCurve(phR, zero, RpR, E, smid, I(0.), wRange(I(smid), t0R), cR, I(0.), N);
      G gr = tipQuantities(jr, KR, wpRange(I(smid), t0R), sym(Ku), false);
      cout << "c = cR:  g(smid) in " << gr.g << "   V in " << gr.V << endl;
      CHECK("(C) g(smid,cR) > 0", gr.g > 0.);
      CHECK("(C) |V| <= rs at c = cR", subset(gr.V, sym(rs)));
    }
    // (B) g_s changes sign across S for every c in J
    {
      // endpoints s = smid -/+ Delta taken exactly (s0 = smid, thin offset -/+Delta)
      Jet jl = jetCurve(phat, dphat, RpJ, E, smid, I(-Delta), wRange(I(smid) - I(Delta), t0J), cmid, dcJ, N);
      G gl = tipQuantities(jl, KJ, wpRange(I(smid) - I(Delta), t0J), sym(Ku), false);
      Jet jr = jetCurve(phat, dphat, RpJ, E, smid, I(Delta), wRange(I(smid) + I(Delta), t0J), cmid, dcJ, N);
      G gr = tipQuantities(jr, KJ, wpRange(I(smid) + I(Delta), t0J), sym(Ku), false);
      cout << "g_s(smid - Delta, J) in " << gl.gs << endl;
      cout << "g_s(smid + Delta, J) in " << gr.gs << endl;
      CHECK("(B) g_s(smid - Delta, c) > 0 for all c in J", gl.gs > 0.);
      CHECK("(B) g_s(smid + Delta, c) < 0 for all c in J", gr.gs < 0.);
    }
    // (A),(D): g_ss < 0 and g_c > 0 on S x J
    {
      Jet jA = jetCurve(phat, dphat, RpJ, E, smid, sym(Delta), wRange(I(smid) + sym(Delta), t0J), cmid, dcJ, N);
      G gA = tipQuantities(jA, KJ, wpRange(I(smid) + sym(Delta), t0J), sym(Ku), true);
      cout << "on S x J:  g_ss in " << gA.gss << endl;
      cout << "           g_c  in " << gA.gc << endl;
      cout << "           U in " << gA.U << "   V in " << gA.V << endl;
      CHECK("(A) d^2g/ds^2 < 0 on S x J (quadratic tangency)", gA.gss < 0.);
      CHECK("(D) dg/dc > 0 on S x J (generic unfolding)", gA.gc > 0.);
      CHECK("tip stays in W^s_loc chart: |V| <= rs on S x J", subset(gA.V, sym(rs)));
      CHECK("S inside W^u_loc domain", (I(smid) + I(Delta)) < delta_u && (I(smid) - I(Delta)) > 0.);
      if (cshift == 0.0) {
        // tangency point q_* = p + U e_u + V e_s with U = sigma(V), |sigma(V)| <= Ls |V|
        I neu = sqrt(sqr(eu[0]) + sqr(eu[1])), nes = sqrt(sqr(es[0]) + sqr(es[1]));
        I dist = (neu * I(Ls) + nes) * I(mag(gA.V));
        cout << "|q_* - p| <= " << dist.rightBound() << endl;
        CHECK(string(THM) + ": tangency point within the stated distance of p", dist < dec(DIST_dec).leftBound());
      }
    }

    cout << "\nALL CHECKS PASSED: " << ALLOK << endl;
  } catch (exception& e) {
    cout << "\nException: " << e.what() << endl;
    return 1;
  }
  return ALLOK ? 0 : 2;
}
